def matmul(a: list[list[float]], b: list[list[float]]) -> list[list[float]]:
    """Multiply two matrices. a is MxK, b is KxN. Returns MxN result."""
    m = len(a)
    k = len(a[0])
    n = len(b[0])
    result = [[0.0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            for p in range(k):
                result[i][j] += a[i][p] * b[p][j]
    return result
